enum SwiftClientError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case Unauthorized
    case NotFound
    case Cancelled
    case InvalidArgument(message: String
    )
    case Internal(message: String
    )






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

