    typealias SwiftType = SwiftClientError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SwiftClientError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .Unauthorized
        case 2: return .NotFound
        case 3: return .Cancelled
        case 4: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SwiftClientError, into buf: inout [UInt8]) {
        switch value {





        case .Unauthorized:
            writeInt(&buf, Int32(1))


        case .NotFound:
            writeInt(&buf, Int32(2))


        case .Cancelled:
            writeInt(&buf, Int32(3))


        case let .InvalidArgument(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)


        case let .Internal(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)

        }
    }
}


